// Aplatit un message Tasmota (tele/<appareil...>/SENSOR ou STATE) en line protocol InfluxDB 1.x.
//  - feuilles numeriques -> champs ; "ON"/"OFF" -> 1/0 ; autres chaines ignorees (Time, Id, TempUnit...)
//  - chemins joints par "_" : sensorsCuve_niveauCuve_hauteurEau, DS18B20_Temperature
//  - measurement : SENSOR -> capteurs, STATE -> etat ; tag appareil = <topic>
//  - horodatage = heure de RECEPTION (precision s) : le champ "Time" des cartes est local, sans fuseau.
// CHOIX FLOAT : on n'ecrit JAMAIS le suffixe "i". Sans suffixe, InfluxDB type le champ en float.
// Un champ cree en entier (4180i) refuserait ensuite 4180.5 (erreur "field type conflict") :
// des floats partout evitent ce piege quand une valeur passe d'entier a decimal.
// Topic sur un ou plusieurs niveaux : tele/garage/SENSOR, tele/cave/serveur-rly-cave-v2/STATE
const parties = String(msg.topic || '').split('/');
if (parties.length < 3 || parties[0] !== 'tele') { return null; }
const appareil = parties.slice(1, -1).join('/');
const dernier = parties[parties.length - 1];
const mesure = dernier === 'SENSOR' ? 'capteurs' : (dernier === 'STATE' ? 'etat' : null);
if (!mesure || !appareil) { return null; }

let charge = msg.payload;
if (Buffer.isBuffer(charge)) { charge = charge.toString('utf8'); }
if (typeof charge === 'string') {
    try { charge = JSON.parse(charge); } catch (e) { return null; }
}
if (charge === null || typeof charge !== 'object') { return null; }

const champs = {};
function aplatit(valeur, chemin, profondeur) {
    if (profondeur > 8) { return; }
    if (typeof valeur === 'number') {
        if (isFinite(valeur)) { champs[chemin] = valeur; }
    } else if (typeof valeur === 'boolean') {
        champs[chemin] = valeur ? 1 : 0;
    } else if (typeof valeur === 'string') {
        if (valeur === 'ON') { champs[chemin] = 1; }
        else if (valeur === 'OFF') { champs[chemin] = 0; }
        // toute autre chaine : ignoree
    } else if (valeur !== null && typeof valeur === 'object') {
        for (const cle of Object.keys(valeur)) {
            aplatit(valeur[cle], chemin ? chemin + '_' + cle : cle, profondeur + 1);
        }
    }
}
aplatit(charge, '', 0);

const noms = Object.keys(champs).sort();
if (noms.length === 0) { return null; }

// line protocol : dans une cle ou un tag, echapper virgule, '=' et espace (retours ligne -> espace)
const echappe = (s) => String(s).replace(/[\r\n]+/g, ' ').replace(/([,= ])/g, '\\$1');
const ts = Math.floor(Date.now() / 1000);
const liste = noms.map((n) => echappe(n) + '=' + String(champs[n])).join(',');
msg.payload = mesure + ',appareil=' + echappe(appareil) + ' ' + liste + ' ' + ts;
return msg;

// Authentification InfluxDB (facultative) par variables d'environnement de l'onglet / du processus.
// Si INFLUX_USER est vide, aucun en-tete : InfluxDB sans auth.
const user = env.get('INFLUX_USER');
const mdp = env.get('INFLUX_PASSWORD');
msg.headers = { 'Content-Type': 'text/plain; charset=utf-8' };
if (user) {
    msg.headers.Authorization = 'Basic ' + Buffer.from(user + ':' + (mdp || '')).toString('base64');
}
return msg;
